INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Projektstart immer mit einem Kick-off-Meeting verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Kick-off optional, aber üblich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Projektstarts?', 3, '[{"text": "Projektziele definieren", "correct": true, "because": "Legt Grundlage für Erfolg"}, {"text": "Projekt abschließen", "correct": false, "because": "Falsche Phase"}, {"text": "Manuelle Umsetzung", "correct": false, "because": "Planung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten gehören typischerweise zum Projektstart?', 5, '[{"text": "Ressourcenplanung", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Stakeholder-Analyse", "correct": true, "because": "Identifiziert Beteiligte"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht projektbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Projektstart legt den Zeitplan fest. b) Er umfasst die Umsetzung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Durchführungsphase"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Projektstart?', 4, '[{"text": "Projektziele", "correct": false, "because": "Definiert Erfolg"}, {"text": "Rollenzuweisung", "correct": false, "because": "Klärt Verantwortung"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Start"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Projektstart für alle Projekte gleich ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Projektart"}, {"text": "Ja", "correct": false, "because": "Variiert je nach Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe ist beim Projektstart entscheidend?', 3, '[{"text": "Zieldefinition", "correct": true, "because": "Leitet gesamtes Projekt"}, {"text": "Abschlussbericht", "correct": false, "because": "Falsche Phase"}, {"text": "Manuelle Dokumentation", "correct": false, "because": "Strukturierte Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumente entstehen oft beim Projektstart?', 5, '[{"text": "Projektcharta", "correct": true, "because": "Definiert Rahmen"}, {"text": "Zeitplan", "correct": true, "because": "Plant Ablauf"}, {"text": "Marketingpläne", "correct": false, "because": "Nicht startrelevant"}, {"text": "Grafikdesigns", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Projektstart klärt Rollen. b) Er ist unwichtig für den Erfolg. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Projektstart?', 4, '[{"text": "Stakeholder-Liste", "correct": false, "because": "Klärt Beteiligte"}, {"text": "Projektziele", "correct": false, "because": "Leiten Ablauf"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Start"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Projektstart nur für das Team relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Betrifft auch Stakeholder"}, {"text": "Ja", "correct": false, "because": "Breite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind beim Projektstart typisch?', 4, '[{"text": "Kick-off-Meeting", "correct": true, "because": "Startet Kommunikation"}, {"text": "Ressourcenplanung", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Abschlussbericht", "correct": false, "because": "Falsche Phase"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Projektstart immer schnell erfolgt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Erfordert sorgfältige Planung"}, {"text": "Ja", "correct": false, "because": "Zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Projektstart?', 3, '[{"text": "Klare Ziele", "correct": true, "because": "Leiten Projekt"}, {"text": "Maximale Details", "correct": false, "because": "Klarheit wichtiger"}, {"text": "Manuelle Planung", "correct": false, "because": "Vorlagen effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Projektstart definiert Verantwortlichkeiten. b) Er umfasst die Durchführung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nächste Phase"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein guter Projektstart?', 5, '[{"text": "Klare Ausrichtung", "correct": true, "because": "Ziele definiert"}, {"text": "Team-Motivation", "correct": true, "because": "Kick-off inspiriert"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Einmalige Nutzung", "correct": false, "because": "Langfristige Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Projektstart unwichtig?', 3, '[{"text": "Ressourcenplanung", "correct": false, "because": "Sichert Umsetzung"}, {"text": "Stakeholder", "correct": false, "because": "Bestimmen Einfluss"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Startfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Projektstart für agile Projekte relevant ist?', 2, '[{"text": "Ja", "correct": true, "because": "Legt Vision und Rahmen"}, {"text": "Nein", "correct": false, "because": "Auch in Agile nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Umfasst der Projektstart die Kostenanalyse?', 3, '[{"text": "Ja", "correct": true, "because": "Teil der Planung"}, {"text": "Nein", "correct": false, "because": "Budget oft definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zum Projektstart?', 4, '[{"text": "Planung eines IT-Projekts", "correct": true, "because": "Definiert Ziele und Team"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Projektphase"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
